import { createElement, useId, type CSSProperties, type SVGAttributes } from "react";

export interface IconProps extends Omit<SVGAttributes<SVGSVGElement>, "children"> {
  size?: number | string;
  color?: string;
  filled?: boolean;
  className?: string;
  style?: CSSProperties;
}

export type IconType = (props: IconProps) => JSX.Element;

function icon(d: string, solid?: string): IconType {
  return function Icon({ size = 24, color = "currentColor", filled, ...rest }) {
    return createElement(
      "svg",
      {
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: color,
        ...rest,
      },
      createElement("path", { d: filled && solid ? solid : d }),
    );
  };
}

interface CutIconProps extends Omit<IconProps, "filled"> {
  live?: boolean;
}

export type CutIconType = (props: CutIconProps) => JSX.Element;

function cutIcon(d: string, base: string, cut: string): CutIconType {
  return function CutIcon({ size = 24, color = "currentColor", live, ...rest }) {
    const id = useId().replace(/:/g, "");
    const svg = {
      xmlns: "http://www.w3.org/2000/svg",
      width: size,
      height: size,
      viewBox: "0 0 24 24",
      fill: color,
      ...rest,
    };
    if (!live) return createElement("svg", svg, createElement("path", { d }));
    return createElement(
      "svg",
      svg,
      createElement("mask", {
        id,
        maskUnits: "userSpaceOnUse",
        x: -2,
        y: -2,
        width: 28,
        height: 28,
        dangerouslySetInnerHTML: {
          __html: `<rect x="-2" y="-2" width="28" height="28" fill="#fff"/>${cut}`,
        },
      }),
      createElement("path", { d: base, mask: `url(#${id})` }),
    );
  };
}

